src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    split = None
    for r, row in enumerate(grid):
        if row and len(set(row)) == 1 and r == h - r - 1:
            split = ("row", r)
            break
    if split is None:
        for c in range(w):
            if len({row[c] for row in grid}) == 1 and c == w - c - 1:
                split = ("col", c)
                break
    if split is None:
        raise ValueError("No centered uniform divider found")
    axis, i = split
    if axis == "row":
        a, b = grid[:i], grid[i + 1:]
    else:
        a = [row[:i] for row in grid]
        b = [row[i + 1:] for row in grid]
    shared = set(v for row in a for v in row) & set(v for row in b for v in row)
    bg = max(shared, key=lambda v: sum(x == v for row in a for x in row) + sum(x == v for row in b for x in row))
    return [[3 if a[r][c] == bg and b[r][c] == bg else bg for c in range(len(a[0]))] for r in range(len(a))]
'''
